import random
import asyncio
from sc2 import maps, run_game, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.bot_ai import BotAI
from sc2.ids.unit_typeid import UnitTypeId
from sc2.ids.ability_id import AbilityId
from sc2.ids.upgrade_id import UpgradeId
from sc2.position import Point2

class ZergRushBot(BotAI):
    async def on_start(self):
        await self.client.game_step(2)
        self.rushed = False
        self.chat_sent = False

    async def on_step(self, iteration):
        # Send a chat message at the start of the game
        if not self.chat_sent:
            await self.chat_send("GL HF! Prepare for the Zerg rush!")
            self.chat_sent = True

        # Distribute workers to resources
        await self.distribute_workers()

        # Inject hatcheries with larva
        await self.inject_hatcheries()

        # Build Overlords if supply is low
        if self.supply_left < 2 and self.can_afford(UnitTypeId.OVERLORD):
            for larva in self.larva.idle:
                await self.do(larva.train(UnitTypeId.OVERLORD))
                break

        # Build Spawning Pool if we don't have one
        if not self.structures(UnitTypeId.SPAWNINGPOOL).exists and self.can_afford(UnitTypeId.SPAWNINGPOOL):
            await self.build(UnitTypeId.SPAWNINGPOOL, near=self.townhalls.first.position.towards(self.game_info.map_center, 5))

        # Build Extractor if we don't have one and Spawning Pool is started
        if self.structures(UnitTypeId.SPAWNINGPOOL).exists and self.structures(UnitTypeId.EXTRACTOR).amount < 1:
            for vg in self.vespene_geyser.closer_than(10, self.townhalls.first):
                if self.can_afford(UnitTypeId.EXTRACTOR):
                    worker = self.select_build_worker(vg.position)
                    if worker and not self.gas_buildings.closer_than(1, vg).exists:
                        await self.do(worker.build(UnitTypeId.EXTRACTOR, vg))
                        break

        # Train Zerglings as soon as possible
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready.exists:
            for larva in self.larva.idle:
                if self.can_afford(UnitTypeId.ZERGLING):
                    await self.do(larva.train(UnitTypeId.ZERGLING))

        # Research Metabolic Boost (Zergling Speed)
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready.exists:
            pool = self.structures(UnitTypeId.SPAWNINGPOOL).ready.first
            if self.can_afford(UpgradeId.ZERGLINGMOVEMENTSPEED) and not self.already_pending_upgrade(UpgradeId.ZERGLINGMOVEMENTSPEED):
                abilities = await self.get_available_abilities(pool)
                if AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST in abilities:
                    await self.do(pool(AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST))

        # Build more Hatcheries if minerals allow and we have enough Zerglings
        if self.units(UnitTypeId.ZERGLING).amount > 20 and self.can_afford(UnitTypeId.HATCHERY):
            location = await self.get_next_expansion()
            if location:
                await self.build(UnitTypeId.HATCHERY, near=location)

        # Attack enemy structures with Zerglings
        if self.units(UnitTypeId.ZERGLING).amount > 10:
            target = self.enemy_structures.random_or(self.enemy_start_locations[0])
            for zergling in self.units(UnitTypeId.ZERGLING).idle:
                await self.do(zergling.attack(target.position))

        # Draw creep pixelmap for debugging
        await self.draw_creep_pixelmap()

    async def inject_hatcheries(self):
        for queen in self.units(UnitTypeId.QUEEN).ready:
            abilities = await self.get_available_abilities(queen)
            if AbilityId.EFFECT_INJECTLARVA in abilities:
                hatch = self.townhalls.ready.closest_to(queen)
                await self.do(queen(AbilityId.EFFECT_INJECTLARVA, hatch))

    async def draw_creep_pixelmap(self):
        creep = self.state.creep
        for y in range(0, creep.height, 8):
            for x in range(0, creep.width, 8):
                if creep.data[y][x]:
                    pos = Point2((x, y))
                    await self._client.debug_sphere_out(pos, 0.5, color=(255, 0, 255))

    async def on_end(self, result):
        print(f"Game ended with result: {result}")

if __name__ == "__main__":
    run_game(
        maps.get("AbyssalReefLE"),
        [
            Bot(Race.Zerg, ZergRushBot()),
            Computer(Race.Terran, Difficulty.Medium)
        ],
        realtime=False,
        save_replay_as="zerg_rush_bot.SC2Replay"
    )
